    source: "ANSA",
    url: "https://www.ansa.it/sito/notizie/mondo/2026/08/19/effetto-domino-anche-vienna-rimanda-i-migranti-in-italia_855429d5-22cd-41c3-b73d-506760b01526.html",
    time: "12 ore fa",
    pub_ts: 1787168983,
    published_at: "2026-08-19T19:49:43+00:00",
    language: "it",
    score: 1,
